import{_ as t,o as r,c as a,ae as o}from"./chunks/framework.CLL1HkDi.js";const g=JSON.parse('{"title":"Features","description":"","frontmatter":{},"headers":[],"relativePath":"guide/protection.md","filePath":"guide/protection.md"}'),s={name:"guide/protection.md"};function i(n,e,l,u,c,d){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h1><p>Plots offers a variety of features to make plot management easy and flexible.</p><h2 id="world-generation" tabindex="-1">World Generation <a class="header-anchor" href="#world-generation" aria-label="Permalink to &quot;World Generation&quot;">​</a></h2><p>The plugin includes a custom world generator that creates a grid-based terrain. You can configure:</p><ul><li><strong>Plot Dimensions:</strong> Custom X and Z sizes.</li><li><strong>Road Width:</strong> Configurable spacing between plots.</li><li><strong>Materials:</strong> Bedrock, surface, and sub-surface blocks can be customized.</li><li><strong>Fluids:</strong> Support for liquid backgrounds (like water for islands).</li></ul><h2 id="smart-prefabs" tabindex="-1">Smart Prefabs <a class="header-anchor" href="#smart-prefabs" aria-label="Permalink to &quot;Smart Prefabs&quot;">​</a></h2><p>Unlike traditional plot plugins that just fill area with blocks, OverworldPlots uses Hytale&#39;s prefab system:</p><ul><li><strong>Automatic Centralization:</strong> If a prefab is smaller than the plot, it is automatically centered.</li><li><strong>Skip-Air Logic:</strong> Background blocks (like water) show through &quot;Empty&quot; areas of your prefab.</li><li><strong>Anchor Support:</strong> Uses prefab anchors for precise vertical and horizontal alignment.</li></ul><h2 id="protection-system" tabindex="-1">Protection System <a class="header-anchor" href="#protection-system" aria-label="Permalink to &quot;Protection System&quot;">​</a></h2><ul><li><strong>Grief Protection:</strong> Only owners and trusted players can build.</li><li><strong>Fluid Flow:</strong> Prevents liquids from spreading into roads or other plots.</li><li><strong>BuilderTools Integration:</strong> BlockMask support and packet interception to ensure even complex operations respect plot boundaries.</li></ul>',10)])])}const f=t(s,[["render",i]]);export{g as __pageData,f as default};
